# Hex values for [1-byte, 2-byte, 3-byte  4-byte] encodings
samples = [
    bytes.fromhex("7F"),           # 127 (1-byte)
    bytes.fromhex("81 00"),        # 128 (2-byte)
    bytes.fromhex("C0 00 00 01"),  # 65536 (4-byte)

    bytes.fromhex("AC 24 B5"),
    bytes.fromhex("EA C2 56 4E"),


]

for b in samples:
    val, size = decode_compressed_unsigned(b)
    print(f"Bytes: {b.hex()} → Value: {val}, Size: {size} bytes")








